const SUFFIXES = new Set(['flow', 'scene', 'object', 'record', 'prototype', 'component'])
const RESERVED_KEYS = new Set(['__proto__', 'prototype', 'constructor'])

function stripJsonComments(source) {
  let output = ''
  let quote = false
  let escaped = false
  let lineComment = false
  let blockComment = false
  for (let index = 0; index < source.length; index += 1) {
    const char = source[index]
    const next = source[index + 1]
    if (lineComment) {
      if (char === '\n') { lineComment = false; output += char } else output += ' '
    } else if (blockComment) {
      if (char === '*' && next === '/') { output += '  '; index += 1; blockComment = false }
      else output += char === '\n' ? '\n' : ' '
    } else if (quote) {
      output += char
      if (escaped) escaped = false
      else if (char === '\\') escaped = true
      else if (char === '"') quote = false
    } else if (char === '"') { quote = true; output += char }
    else if (char === '/' && next === '/') { lineComment = true; output += '  '; index += 1 }
    else if (char === '/' && next === '*') { blockComment = true; output += '  '; index += 1 }
    else output += char
  }
  return output.replace(/,\s*([}\]])/g, '$1')
}

function templateValues(value, context) {
  if (typeof value === 'string') return value.replace(/\$\{([^}]+)\}/g, (token, name) => Object.hasOwn(context, name) ? context[name] : token)
  if (Array.isArray(value)) return value.map(item => templateValues(item, context))
  if (value && typeof value === 'object') {
    return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, templateValues(item, context)]))
  }
  return value
}

function identityFor(path, suffix, identityProfile) {
  const parts = path.replace(/\\/g, '/').split('/').filter(Boolean)
  const filename = parts.pop()
  const basename = filename.replace(/\.(?:flow|scene|object|record|prototype|component)\.(?:json|jsonc)$/i, '')
  const prototypeContent = parts.includes('prototypes')
  if (!prototypeContent) return { name: basename, scope: null }
  let segments = parts
  if (segments[0] === 'source' || segments[0] === 'src') segments = segments.slice(1)
  if (segments[0] === 'prototypes') segments = segments.slice(1)
  if (identityProfile === 'hypercanvas') {
    const folderRoot = segments[0]?.endsWith('.folder')
    segments = segments.map(segment => segment.endsWith('.folder') ? segment.slice(0, -7) : segment)
    if (folderRoot) segments = segments.slice(1)
  }
  segments = segments.filter(segment => segment && (identityProfile !== 'hypercanvas' || !segment.endsWith('.folder')))

  if (segments.length === 0) return { name: basename, scope: null }
  const prototype = segments[0]
  const nested = segments.slice(1)
  if (suffix === 'prototype') return { name: prototype, scope: prototype }
  return { name: `${prototype}/${[...nested, basename].join('/')}`, scope: prototype }
}

export function buildDataIndex({ files = [], readFile, mode = 'development', identityProfile = 'standalone', policy = {} } = {}) {
  if (typeof readFile !== 'function') throw new TypeError('buildDataIndex requires a readFile(path) function.')
  const index = { flows: {}, objects: {}, records: {}, prototypes: {}, components: {} }
  const origins = new Map()
  const diagnostics = []
  const dependencies = []
  for (const entry of files) {
    const file = typeof entry === 'string' ? entry : entry.path
    if (!file) continue
    const root = typeof entry === 'string' ? '' : (entry.root ?? '')
    const normalized = (typeof entry === 'string' ? file : (entry.identityPath ?? `${root}/${file}`)).replace(/\\/g, '/').replace(/^\.\//, '').replace(/\/+/g, '/')
    const parts = normalized.split('/')
    if (parts.some(part => part.startsWith('_')) || policy.ignorePrefixes?.some(prefix => normalized.startsWith(prefix))) continue
    const isDraft = parts.includes('drafts')
    if (isDraft && (mode === 'production' || policy.includeDrafts === false)) continue
    const match = normalized.match(/\.([^.]+)\.(?:json|jsonc)$/i)
    if (!match || !SUFFIXES.has(match[1])) continue
    const suffix = match[1].toLowerCase()
    const resolvedFile = typeof entry === 'string' ? file : (entry.displayPath ?? entry.path)
    const dependency = typeof entry === 'string' ? file : entry.path
    dependencies.push(dependency)
    const selectedIdentityProfile = typeof entry === 'string' ? identityProfile : (entry.identityProfile ?? identityProfile)
    const identity = identityFor(normalized, suffix === 'scene' ? 'flow' : suffix, selectedIdentityProfile)
    if (typeof entry !== 'string' && entry.scope) {
      if (identity.name === identity.scope) identity.name = entry.scope
      else if (identity.scope) identity.name = `${entry.scope}/${identity.name.slice(identity.scope.length + 1)}`
      else identity.name = `${entry.scope}/${identity.name}`
      identity.scope = entry.scope
    }
    const type = suffix === 'scene' ? 'flow' : suffix
    const name = identity.name
    const collectionName = type === 'flow' ? 'flows' : type === 'object' ? 'objects' : type === 'record' ? 'records' : type === 'prototype' ? 'prototypes' : 'components'
    const key = type === 'prototype' ? identity.scope ?? name : name
    const identityKey = `${type}:${key}`
    const previous = origins.get(identityKey)
    if (previous) {
      diagnostics.push({ code: 'DUPLICATE_IDENTITY', severity: 'error', file: resolvedFile, message: `Duplicate ${type} "${key}" also declared by ${previous}.` })
      continue
    }
    origins.set(identityKey, resolvedFile)
    try {
      let value = JSON.parse(stripJsonComments(readFile(typeof entry === 'string' ? resolvedFile : entry.path)))
      const dirname = normalized.slice(0, normalized.lastIndexOf('/'))
      const protoAt = parts.findIndex(part => part === 'prototypes')
      const protoPath = protoAt < 0 ? '' : parts.slice(0, protoAt + 2).join('/')
      const context = {
        currentDir: dirname,
        currentProto: protoPath,
        currentProtoDir: protoPath ? protoPath.slice(0, protoPath.lastIndexOf('/')) : '',
      }
      if (policy.templates !== false) value = templateValues(value, context)
      if (type === 'flow' && identityProfile === 'hypercanvas' && policy.inferFlowRoute) {
        value = value && typeof value === 'object' && !Array.isArray(value) ? { ...value, _route: `/${name.split('/').slice(1).join('/')}` } : value
      }
      if (isDraft && value && typeof value === 'object' && !Array.isArray(value)) value = { ...value, _statefully: { ...(value._statefully ?? {}), private: true } }
      if (RESERVED_KEYS.has(key)) throw new Error(`Reserved data index key: ${key}`)
      index[collectionName][key] = value
    } catch (error) {
      diagnostics.push({ code: 'INVALID_DATA_FILE', severity: 'error', file: resolvedFile, message: error.message })
    }
  }
  if (mode === 'production' && diagnostics.some(item => item.severity === 'error')) {
    const errors = diagnostics.filter(item => item.severity === 'error')
    throw new AggregateError(errors.map(item => new Error(item.message)), `Statefully data discovery failed: ${errors.map(item => item.message).join(' ')}`)
  }
  return { index, diagnostics, dependencies: [...new Set(dependencies)] }
}
