function readStorage(storage, key) {
  try { return storage?.getItem(key) ?? null } catch { return null }
}

export function createThemeStore({
  defaultTheme = 'system',
  storage,
  namespace = 'statefully',
  key = 'prototype-theme',
  targetDocument,
  applyToDocument = false,
} = {}) {
  const storageKey = namespace ? `${namespace}:${key}` : key
  const persisted = readStorage(storage, storageKey)
  let current = persisted ?? defaultTheme
  const listeners = new Set()
  let disposed = false
  return Object.freeze({
    getTheme() { return current },
    setTheme(theme) {
      current = theme
      try { storage?.setItem(storageKey, theme) } catch {}
      if (applyToDocument) targetDocument?.documentElement?.setAttribute('data-prototype-theme', theme)
      listeners.forEach(listener => listener())
    },
    subscribe(listener) {
      if (disposed) return () => {}
      listeners.add(listener)
      return () => listeners.delete(listener)
    },
    dispose() { disposed = true; listeners.clear() },
  })
}

let defaultThemeStore = createThemeStore()

export function getTheme() { return defaultThemeStore.getTheme() }
export function setTheme(theme) { return defaultThemeStore.setTheme(theme) }
export function subscribeToTheme(listener) { return defaultThemeStore.subscribe(listener) }

// Explicit legacy initializer. DOM and storage effects occur only when called.
export function initTheme(defaultTheme = 'system', { namespace = '', key = 'prototype-theme' } = {}) {
  let storage
  try { storage = typeof localStorage !== 'undefined' ? localStorage : undefined } catch {}
  const targetDocument = typeof document !== 'undefined' ? document : undefined
  defaultThemeStore = createThemeStore({
    defaultTheme,
    storage,
    namespace,
    key,
    targetDocument,
    applyToDocument: true,
  })
  defaultThemeStore.setTheme(defaultThemeStore.getTheme())
  return defaultThemeStore.getTheme()
}
