export class StatefullyDataError extends Error {
  constructor(code, message, details = {}) {
    super(message)
    this.name = 'StatefullyDataError'
    this.code = code
    this.details = details
  }
}

export function deepClone(value) {
  if (value == null || typeof value !== 'object') return value
  if (typeof structuredClone === 'function') return structuredClone(value)
  if (Array.isArray(value)) return value.map(deepClone)
  return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, deepClone(item)]))
}

export function deepMerge(target = {}, source = {}) {
  const result = { ...target }
  for (const [key, sourceValue] of Object.entries(source)) {
    const targetValue = target[key]
    if (
      sourceValue && typeof sourceValue === 'object' && !Array.isArray(sourceValue) &&
      targetValue && typeof targetValue === 'object' && !Array.isArray(targetValue)
    ) {
      result[key] = deepMerge(targetValue, sourceValue)
    } else {
      result[key] = deepClone(sourceValue)
    }
  }
  return result
}

function normalizeIndex(value = {}) {
  return {
    flows: deepClone(value.flows ?? value.scenes ?? {}),
    objects: deepClone(value.objects ?? {}),
    records: deepClone(value.records ?? {}),
    prototypes: deepClone(value.prototypes ?? {}),
  }
}

function scopedCandidates(name, { prototype, dataset } = {}) {
  const candidates = []
  if (typeof name !== 'string' || !name) return candidates
  if (name.includes('/')) candidates.push(name)
  const datasetName = dataset ? `${dataset}/${name}` : null
  if (prototype) {
    if (datasetName) candidates.push(`${prototype}/${datasetName}`)
    candidates.push(`${prototype}/${name}`)
  }
  if (datasetName) candidates.push(datasetName)
  candidates.push(name)
  return [...new Set(candidates)]
}

function resolveName(collection, name, options, { caseInsensitive = false } = {}) {
  const candidates = scopedCandidates(name, options)
  for (const candidate of candidates) {
    if (collection[candidate] != null) return candidate
  }
  if (caseInsensitive) {
    const key = Object.keys(collection).find(candidate => candidate.toLowerCase() === String(name).toLowerCase())
    if (key) return key
  }
  return null
}

function errorForMissing(type, name, collection) {
  const available = Object.keys(collection)
  const related = available.filter(key => key.endsWith(`/${name}`) || key.startsWith(`${name}/`)).slice(0, 5)
  const hint = related.length ? ` Did you mean: ${related.join(', ')}?` : ''
  return new StatefullyDataError('DATA_NOT_FOUND', `${type} not found: ${name}.${hint}`, { type, name, available })
}

export function getByPath(value, path) {
  if (path == null || path === '') return value
  return String(path).split('.').reduce((current, key) => current?.[key], value)
}

export function setByPath(value, path, next) {
  if (!value || typeof value !== 'object' || !path) return value
  const keys = String(path).split('.')
  let cursor = value
  for (let index = 0; index < keys.length - 1; index += 1) {
    const key = keys[index]
    if (key === '__proto__' || key === 'prototype' || key === 'constructor') return value
    const nextKey = keys[index + 1]
    if (cursor[key] == null || typeof cursor[key] !== 'object') {
      cursor[key] = /^\d+$/.test(nextKey) ? [] : {}
    }
    cursor = cursor[key]
  }
  const finalKey = keys.at(-1)
  if (!['__proto__', 'prototype', 'constructor'].includes(finalKey)) cursor[finalKey] = next
  return value
}

export function createPrototypeStore(initialIndex = {}, options = {}) {
  let index = normalizeIndex(initialIndex)
  let version = 0
  const listeners = new Set()
  const notify = () => listeners.forEach(listener => listener())
  const scoped = (name, scopeOptions = {}) => ({
    prototype: scopeOptions.prototype ?? options.prototype,
    dataset: scopeOptions.dataset ?? options.dataset,
  })

  function resolveObjectName(scope, name, dataset) {
    const key = resolveName(index.objects, name, { prototype: scope, dataset })
    return key ?? (scope ? `${scope}/${name}` : name)
  }

  function resolveRecordName(scope, name, dataset) {
    const key = resolveName(index.records, name, { prototype: scope, dataset })
    return key ?? (scope ? `${scope}/${name}` : name)
  }

  function resolveFlowName(scope, name, dataset) {
    const opts = { prototype: scope, dataset }
    const key = resolveName(index.flows, name, opts, { caseInsensitive: true })
    return key ?? (scope ? `${scope}/${name}` : name)
  }

  function loadObject(name, scopeOptions = {}) {
    const opts = typeof scopeOptions === 'string' ? { prototype: scopeOptions } : scopeOptions
    const resolvedOptions = scoped(name, opts)
    const key = resolveName(index.objects, name, resolvedOptions)
    if (!key) throw errorForMissing('Object', name, index.objects)
    return resolveRefs(deepClone(index.objects[key]), new Set(), resolvedOptions)
  }

  function resolveRefs(value, seen = new Set(), scopeOptions = {}) {
    if (value == null || typeof value !== 'object') return value
    if (Array.isArray(value)) return value.map(item => resolveRefs(item, seen, scopeOptions))
    if (typeof value.$ref === 'string') {
      const key = resolveName(index.objects, value.$ref, scopeOptions)
      if (!key) throw errorForMissing('Data reference', value.$ref, index.objects)
      if (seen.has(key)) {
        throw new StatefullyDataError('CIRCULAR_REFERENCE', `Circular $ref detected: ${[...seen, key].join(' → ')}`, { chain: [...seen, key] })
      }
      const next = new Set(seen)
      next.add(key)
      return resolveRefs(index.objects[key], next, scopeOptions)
    }
    return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, resolveRefs(item, seen, scopeOptions)]))
  }

  function loadFlow(name = 'default', scopeOptions = {}) {
    const optionsForCall = scoped(name, scopeOptions)
    const key = resolveName(index.flows, name, optionsForCall, { caseInsensitive: true })
    if (!key) throw errorForMissing('Flow', name, index.flows)
    if (key !== name && key.toLowerCase() === String(name).toLowerCase()) {
      console.warn(`[statefully] Flow name casing differs: requested "${name}", found "${key}".`)
    }
    const flowScope = optionsForCall.prototype ?? (key.includes('/') ? key.split('/')[0] : null)
    const flowOptions = { ...optionsForCall, prototype: flowScope }
    let flow = deepClone(index.flows[key])
    if (!flow || typeof flow !== 'object' || Array.isArray(flow)) {
      throw new StatefullyDataError('INVALID_FLOW', `Flow "${key}" must contain an object at its root.`, { name: key })
    }
    if (Array.isArray(flow.$global)) {
      const names = flow.$global
      delete flow.$global
      let globals = {}
      for (const globalName of names) {
        try {
          let value
          const objectKey = resolveName(index.objects, globalName, flowOptions)
          if (objectKey) value = index.objects[objectKey]
          else {
            const flowKey = resolveName(index.flows, globalName, flowOptions, { caseInsensitive: true })
            if (!flowKey) throw errorForMissing('$global entry', globalName, index.objects)
            value = index.flows[flowKey]
          }
          globals = deepMerge(globals, resolveRefs(value, new Set(), flowOptions))
        } catch (error) {
          console.warn(`[statefully] Failed to load $global "${globalName}" in "${key}".`, error)
        }
      }
      flow = deepMerge(globals, flow)
    }
    return deepClone(resolveRefs(flow, new Set(), flowOptions))
  }

  function loadRecord(name, scopeOptions = {}) {
    const opts = typeof scopeOptions === 'string' ? { prototype: scopeOptions } : scopeOptions
    const resolvedOptions = scoped(name, opts)
    const key = resolveName(index.records, name, resolvedOptions)
    if (!key) throw errorForMissing('Record', name, index.records)
    const value = index.records[key]
    if (!Array.isArray(value)) {
      throw new StatefullyDataError('INVALID_RECORD', `Record "${key}" must be an array.`, { name: key })
    }
    return deepClone(value)
  }

  function findRecord(name, id, scopeOptions = {}) {
    return loadRecord(name, scopeOptions).find(item => String(item?.id) === String(id)) ?? null
  }

  const store = {
    getIndex: () => deepClone(index),
    replaceIndex(next) { index = normalizeIndex(next); version += 1; notify() },
    getSnapshot() { return version },
    subscribe(listener) { listeners.add(listener); return () => listeners.delete(listener) },
    loadFlow,
    loadObject,
    loadRecord,
    findRecord,
    listFlows(scope) {
      const names = Object.keys(index.flows)
      return scope ? names.filter(name => name.startsWith(`${scope}/`)) : names
    },
    resolveFlowName,
    resolveObjectName,
    resolveRecordName,
  }
  return Object.freeze(store)
}

let defaultStore = createPrototypeStore()

export function init(index = {}) {
  defaultStore.replaceIndex(index)
}

export function getDefaultStore() { return defaultStore }
export function getIndex() { return defaultStore.getIndex() }
export function loadFlow(...args) { return defaultStore.loadFlow(...args) }
export function loadObject(...args) { return defaultStore.loadObject(...args) }
export function loadRecord(...args) { return defaultStore.loadRecord(...args) }
export function findRecord(...args) { return defaultStore.findRecord(...args) }
export function listFlows(...args) { return defaultStore.listFlows(...args) }
export function flowExists(name) { return defaultStore.listFlows().some(key => key.toLowerCase() === String(name).toLowerCase()) }
export function resolveFlowName(...args) { return defaultStore.resolveFlowName(...args) }
export function resolveObjectName(...args) { return defaultStore.resolveObjectName(...args) }
export function resolveRecordName(...args) { return defaultStore.resolveRecordName(...args) }
export const loadScene = loadFlow
export const listScenes = listFlows
export const sceneExists = flowExists
