function getWindow(targetWindow) {
  return targetWindow ?? (typeof window !== 'undefined' ? window : null)
}

function splitHash(hash = '') {
  const raw = String(hash).replace(/^#/, '')
  if (raw.startsWith('/')) {
    const queryIndex = raw.indexOf('?')
    return {
      path: queryIndex < 0 ? raw : raw.slice(0, queryIndex),
      query: queryIndex < 0 ? '' : raw.slice(queryIndex + 1),
    }
  }
  return { path: '', query: raw }
}

function parseHashParams(targetWindow) {
  const win = getWindow(targetWindow)
  return new URLSearchParams(splitHash(win?.location?.hash).query)
}

function writeParams(targetWindow, params) {
  const win = getWindow(targetWindow)
  if (!win?.location) return
  const { path } = splitHash(win.location.hash)
  const query = params.toString()
  if (path && query) win.location.hash = `${path}?${query}`
  else if (path) win.location.hash = path
  else win.location.hash = query
}

function storageOrNull(candidate) {
  if (candidate) return candidate
  try {
    return typeof localStorage !== 'undefined' ? localStorage : null
  } catch {
    return null
  }
}

export function createSessionStore({ targetWindow, storage, namespace = 'statefully', route } = {}) {
  const win = getWindow(targetWindow)
  let storageTarget
  try { storageTarget = storageOrNull(storage ?? win?.localStorage) } catch { storageTarget = null }
  const listeners = new Set()
  const storageListeners = new Set()
  let listening = false
  let disposed = false
  let storageSnapshot = ''

  const notify = () => listeners.forEach(listener => listener())
  const notifyStorage = () => {
    storageSnapshot = JSON.stringify(getAllLocal())
    storageListeners.forEach(listener => listener())
    notify()
  }
  const onHashChange = () => notify()
  const onStorage = event => {
    if (!event?.key || event.key.startsWith(`${namespace}:`)) notifyStorage()
  }
  function attach() {
    if (listening || disposed || !win?.addEventListener) return
    listening = true
    win.addEventListener('hashchange', onHashChange)
    win.addEventListener('storage', onStorage)
  }
  function detach() {
    if (!listening) return
    listening = false
    win?.removeEventListener?.('hashchange', onHashChange)
    win?.removeEventListener?.('storage', onStorage)
  }
  function namespaced(key) { return `${namespace}:${key}` }
  function getAllLocal() {
    if (!storageTarget) return {}
    const result = {}
    for (let index = 0; index < storageTarget.length; index += 1) {
      const key = storageTarget.key(index)
      if (key?.startsWith(`${namespace}:`)) result[key.slice(namespace.length + 1)] = storageTarget.getItem(key)
    }
    return result
  }

  return Object.freeze({
    getParam(key) { return parseHashParams(win).get(key) },
    getAllParams() { return Object.fromEntries(parseHashParams(win).entries()) },
    setParam(key, value) {
      const params = parseHashParams(win)
      params.set(String(key), String(value))
      writeParams(win, params)
      notify()
    },
    removeParam(key) {
      const params = parseHashParams(win)
      params.delete(String(key))
      writeParams(win, params)
      notify()
    },
    replaceParams(values = {}) {
      const params = new URLSearchParams()
      for (const [key, value] of Object.entries(values)) params.set(key, String(value))
      writeParams(win, params)
      notify()
    },
    subscribe(listener) {
      attach()
      listeners.add(listener)
      return () => {
        listeners.delete(listener)
        if (listeners.size === 0 && storageListeners.size === 0) detach()
      }
    },
    getSnapshot() { return win?.location?.hash ?? '' },
    getLocal(key, fallback) {
      if (!storageTarget) return fallback
      const value = storageTarget.getItem(namespaced(key))
      if (value == null) return fallback
      try { return JSON.parse(value) } catch { return value }
    },
    setLocal(key, value) {
      if (!storageTarget) return
      storageTarget.setItem(namespaced(key), typeof value === 'string' ? value : JSON.stringify(value))
      notifyStorage()
    },
    removeLocal(key) {
      storageTarget?.removeItem(namespaced(key))
      notifyStorage()
    },
    getAllLocal,
    subscribeToStorage(listener) {
      attach()
      storageListeners.add(listener)
      storageSnapshot = JSON.stringify(getAllLocal())
      return () => {
        storageListeners.delete(listener)
        if (listeners.size === 0 && storageListeners.size === 0) detach()
      }
    },
    getStorageSnapshot() { return storageSnapshot || JSON.stringify(getAllLocal()) },
    notifyChange: notifyStorage,
    getRoute() { return route ?? null },
    dispose() {
      disposed = true
      detach()
      listeners.clear()
      storageListeners.clear()
    },
  })
}

let defaultSession
export function getDefaultSession() {
  if (!defaultSession) defaultSession = createSessionStore()
  return defaultSession
}

export function getParam(key) { return getDefaultSession().getParam(key) }
export function getAllParams() { return getDefaultSession().getAllParams() }
export function readParams() { return new URLSearchParams(getAllParams()) }
export function setParam(key, value) { return getDefaultSession().setParam(key, value) }
export function removeParam(key) { return getDefaultSession().removeParam(key) }
export function subscribeToSession(listener) { return getDefaultSession().subscribe(listener) }
export function sessionSnapshot() { return getDefaultSession().getSnapshot() }
export const subscribeToHash = subscribeToSession
export const getHashSnapshot = sessionSnapshot

export function getLocal(...args) { return getDefaultSession().getLocal(...args) }
export function setLocal(...args) { return getDefaultSession().setLocal(...args) }
export function removeLocal(...args) { return getDefaultSession().removeLocal(...args) }
export function getAllLocal() { return getDefaultSession().getAllLocal() }
export function subscribeToStorage(listener) { return getDefaultSession().subscribeToStorage(listener) }
export function getStorageSnapshot() { return getDefaultSession().getStorageSnapshot() }
export function notifyChange() { return getDefaultSession().notifyChange() }
