import { getDefaultSession } from './session.js'

function copyParams(params) { return Object.fromEntries(Object.entries(params ?? {})) }

export function createHistoryStore({ session = getDefaultSession(), maxEntries = 200, route } = {}) {
  const limit = Math.max(1, Math.floor(maxEntries) || 200)
  const listeners = new Set()
  let entries = []
  let index = -1
  let applying = false
  const notify = () => listeners.forEach(listener => listener())

  function makeSnapshot() {
    return {
      params: copyParams(session.getAllParams()),
      route: typeof route === 'function' ? route() : route ?? null,
    }
  }
  function sameSnapshot(left, right) {
    return left?.route === right?.route && JSON.stringify(left?.params) === JSON.stringify(right?.params)
  }
  function apply(entry) {
    if (!entry) return false
    applying = true
    session.replaceParams(entry.params)
    applying = false
    notify()
    return true
  }
  function pushSnapshot() {
    if (applying) return false
    const next = makeSnapshot()
    if (sameSnapshot(entries[index], next)) return false
    entries = entries.slice(0, index + 1)
    entries.push(next)
    if (entries.length > limit) entries.shift()
    index = entries.length - 1
    notify()
    return true
  }
  function undo() {
    if (index <= 0) return false
    index -= 1
    return apply(entries[index])
  }
  function redo() {
    if (index >= entries.length - 1) return false
    index += 1
    return apply(entries[index])
  }

  return Object.freeze({
    pushSnapshot,
    undo,
    redo,
    canUndo: () => index > 0,
    canRedo: () => index >= 0 && index < entries.length - 1,
    getCurrentSnapshot: () => entries[index] ? structuredClone(entries[index]) : null,
    getHistory: () => entries.map(entry => structuredClone(entry)),
    getCurrentIndex: () => index,
    subscribe(listener) { listeners.add(listener); return () => listeners.delete(listener) },
    dispose() { listeners.clear(); entries = []; index = -1 },
  })
}

export function installHistorySync({ history, session = getDefaultSession(), pushInitial = true } = {}) {
  if (!history) throw new TypeError('installHistorySync requires a history store')
  if (pushInitial) history.pushSnapshot()
  const unsubscribe = session.subscribe(() => history.pushSnapshot())
  let disposed = false
  return () => {
    if (disposed) return
    disposed = true
    unsubscribe()
  }
}
