import { getDefaultSession } from './session.js'

function normalizeRoute(route) {
  if (route == null || route === '' || route === '/' || route === 'global') return ''
  return String(route).replace(/\\/g, '/').split(/[/.]/).filter(Boolean).join('.')
}

export function buildKnobKey(id, { route, scope } = {}) {
  const scopeName = normalizeRoute(selectedOptionScope({ route, scope }))
  return `knob.${scopeName ? `${scopeName}.` : ''}${id}`
}

function pascal(value) {
  return String(value ?? '').match(/[a-zA-Z0-9]+/g)?.map(part => part.charAt(0).toUpperCase() + part.slice(1)).join('') || ''
}

export function buildLegacyKnobKey(id, { route, scope } = {}) {
  const scopeName = normalizeRoute(selectedOptionScope({ route, scope }))
  return `knob${pascal(scopeName)}${pascal(id)}`
}

export function flattenKnobs(definitions = [], parentId = '', inheritedScope) {
  if (!Array.isArray(definitions)) return []
  const result = []
  for (const definition of definitions) {
    if (!definition || typeof definition !== 'object' || typeof definition.id !== 'string') continue
    const id = parentId ? `${parentId}.${definition.id}` : definition.id
    const hasScope = Object.hasOwn(definition, 'scope') && definition.scope !== undefined
    const scope = hasScope ? definition.scope : inheritedScope
    const flattened = { ...definition, id }
    delete flattened.knobs
    if (scope !== undefined) flattened.scope = scope
    result.push(flattened)
    if (Array.isArray(definition.knobs)) result.push(...flattenKnobs(definition.knobs, id, scope))
  }
  return result
}

function knobKeysFor(id, definition, scope) {
  const normalized = normalizeRoute(scope)
  const keys = [buildKnobKey(id, { scope: normalized })]
  const aliases = definition?.aliases ?? definition?.legacyIds ?? []
  const names = Array.isArray(aliases) ? aliases : typeof aliases === 'string' ? [aliases] : []
  for (const alias of names.filter(name => typeof name === 'string' && name)) {
    keys.push(buildKnobKey(alias, { scope: normalized }))
    if (normalized) keys.push(`knob.${alias}.${normalized}`)
  }
  if (normalized) keys.push(`knob.${id}.${normalized}`)
  for (const aliasScope of scopeAliasesFor(definition)) {
    for (const name of [id, ...names.filter(name => typeof name === 'string' && name)]) {
      keys.push(buildKnobKey(name, { scope: aliasScope }))
      keys.push(`knob.${name}.${aliasScope}`)
    }
  }
  const legacyKeys = definition?.legacyKeys ?? []
  const explicitLegacyKeys = Array.isArray(legacyKeys) ? legacyKeys : typeof legacyKeys === 'string' ? [legacyKeys] : []
  keys.push(...explicitLegacyKeys.filter(key => typeof key === 'string' && key.startsWith('knob')))
  return [...new Set(keys)]
}

function scopeAliasesFor(definition) {
  const aliases = definition?.scopeAliases ?? []
  const names = Array.isArray(aliases) ? aliases : typeof aliases === 'string' ? [aliases] : []
  return [...new Set(names.map(normalizeRoute).filter(Boolean))]
}

function canonicalScopeForDefinition(definition, requestedScope) {
  if (definition && Object.hasOwn(definition, 'scope') && definition.scope !== undefined) {
    const canonical = normalizeRoute(definition.scope)
    if (requestedScope === undefined) return canonical
    const requested = normalizeRoute(requestedScope)
    if (requested === canonical || scopeAliasesFor(definition).includes(requested)) return canonical
  }
  return normalizeRoute(requestedScope)
}

function decode(value) {
  if (typeof value !== 'string') return value
  try { return JSON.parse(value) } catch { return value }
}

function optionValue(option) {
  return option && typeof option === 'object' ? option.value : option
}

function validDate(value) {
  if (typeof value !== 'string' || !/^\d{4}-\d{2}-\d{2}(?:T.*)?$/.test(value)) return false
  const date = new Date(value)
  return !Number.isNaN(date.valueOf()) && date.toISOString().slice(0, 10) === value.slice(0, 10)
}

export function coerce(value, type, fallback, definition = {}) {
  if (value == null) return fallback
  const decoded = decode(value)
  switch (type) {
    case 'boolean':
      if (decoded === true || decoded === 'true') return true
      if (decoded === false || decoded === 'false') return false
      return fallback
    case 'number':
    case 'slider': {
      const number = typeof decoded === 'number' ? decoded : Number(decoded)
      if (!Number.isFinite(number)) return fallback
      if (definition.min != null && number < definition.min) return fallback
      if (definition.max != null && number > definition.max) return fallback
      return number
    }
    case 'range': {
      const values = Array.isArray(decoded) ? decoded : typeof decoded === 'string' ? decoded.split(',') : null
      if (!values || values.length !== 2) return fallback
      const pair = values.map(Number)
      if (!pair.every(Number.isFinite) || pair[0] > pair[1]) return fallback
      if (definition.min != null && pair[0] < definition.min) return fallback
      if (definition.max != null && pair[1] > definition.max) return fallback
      return pair
    }
    case 'select':
    case 'radio': {
      const allowed = (definition.options ?? []).map(optionValue)
      return allowed.some(option => String(option) === String(decoded)) ? decoded : fallback
    }
    case 'string-array': {
      if (!Array.isArray(decoded)) return fallback
      const itemType = definition.itemType ?? 'string'
      if (itemType === 'number') {
        const numbers = decoded.map(item => {
          if (typeof item === 'number') return Number.isFinite(item) ? item : null
          if (typeof item !== 'string' || item.trim() === '') return null
          const number = Number(item)
          return Number.isFinite(number) ? number : null
        })
        return numbers.every(Number.isFinite) ? numbers : fallback
      }
      const valid = decoded.every(item => {
        if (itemType === 'boolean') return typeof item === 'boolean'
        return typeof item === 'string'
      })
      return valid ? decoded : fallback
    }
    case 'object':
      return decoded && typeof decoded === 'object' && !Array.isArray(decoded) ? decoded : fallback
    case 'date':
      return validDate(decoded) ? decoded : fallback
    case 'string':
    case 'textarea':
      return typeof decoded === 'string' ? decoded : String(decoded)
    default:
      if (typeof decoded === 'string') {
        if (decoded === 'true') return true
        if (decoded === 'false') return false
        if (decoded.trim() !== '' && Number.isFinite(Number(decoded))) return Number(decoded)
      }
      return decoded
  }
}

export function serializeKnobValue(value, definition = {}) {
  switch (definition.type) {
    case 'boolean': return value ? 'true' : 'false'
    case 'range': return Array.isArray(value) ? `${value[0]},${value[1]}` : String(value ?? '')
    case 'string-array':
    case 'object': return JSON.stringify(value)
    default:
      if (typeof value === 'object' && value !== null) return JSON.stringify(value)
      return String(value ?? '')
  }
}

function readTargetHash(target) {
  const hash = String(target?.location?.hash ?? '').replace(/^#/, '')
  if (hash.startsWith('/')) {
    const index = hash.indexOf('?')
    return { path: index < 0 ? hash : hash.slice(0, index), params: new URLSearchParams(index < 0 ? '' : hash.slice(index + 1)) }
  }
  return { path: '', params: new URLSearchParams(hash) }
}

function writeTargetHash(target, path, params) {
  if (!target?.location) return
  const query = params.toString()
  target.location.hash = path && query ? `${path}?${query}` : path || query
}

function selectedOptionScope(options = {}) {
  if (Object.hasOwn(options, 'route') && options.route !== undefined) return options.route
  if (Object.hasOwn(options, 'scope') && options.scope !== undefined) return options.scope
  return undefined
}

export function createKnobStore(definitions = [], options = {}) {
  const { session } = options
  const flattened = flattenKnobs(definitions)
  const getSession = () => session ?? getDefaultSession()
  const configuredScope = selectedOptionScope(options)
  const defaultScope = normalizeRoute(configuredScope)
  const definitionScope = definition => Object.hasOwn(definition ?? {}, 'scope') && definition.scope !== undefined ? normalizeRoute(definition.scope) : defaultScope
  function selectDefinition(id, requestedScope, explicit) {
    const preferredScope = explicit ? normalizeRoute(requestedScope) : defaultScope
    const exact = flattened.find(definition => definition.id === id && definitionScope(definition) === preferredScope)
    if (exact) return { definition: exact, scope: definitionScope(exact) }
    const aliased = flattened.find(definition => definition.id === id && scopeAliasesFor(definition).includes(preferredScope))
    if (aliased) return { definition: aliased, scope: definitionScope(aliased) }
    if (!explicit && preferredScope) {
      const global = flattened.find(definition => definition.id === id && definitionScope(definition) === '')
      if (global) return { definition: global, scope: '' }
    }
    return { definition: undefined, scope: preferredScope }
  }
  function resolve(id, requestedScope) {
    return selectDefinition(id, requestedScope, arguments.length > 1).definition
  }
  function keysFor(id, definition, selectedScope) {
    return knobKeysFor(id, definition, selectedScope)
  }
  function getKnob(id, fallback, requestedScope) {
    const selected = selectDefinition(id, requestedScope, arguments.length > 2)
    const sessionStore = getSession()
    let value
    for (const key of keysFor(id, selected.definition, selected.scope)) {
      value = sessionStore.getParam(key)
      if (value != null) break
    }
    return coerce(value, selected.definition?.type, selected.definition?.default ?? fallback, selected.definition)
  }
  function setKnob(id, value, requestedScope) {
    const selected = selectDefinition(id, requestedScope, arguments.length > 2)
    getSession().setParam(buildKnobKey(id, { scope: selected.scope }), serializeKnobValue(value, selected.definition))
  }
  function clearKnob(id, requestedScope) {
    const selected = selectDefinition(id, requestedScope, arguments.length > 1)
    for (const key of keysFor(id, selected.definition, selected.scope)) getSession().removeParam(key)
  }
  function selectedDefinitions(requestedScope, explicit, includeGlobalFallback = true) {
    const ids = [...new Set(flattened.map(definition => definition.id))]
    return ids.map(id => {
      if (!includeGlobalFallback && !explicit) return selectDefinition(id, defaultScope, true)
      return selectDefinition(id, requestedScope, explicit)
    }).filter(item => item.definition)
  }
  function applyPreset(values = {}, requestedScope) {
    const explicit = arguments.length > 1
    const entries = values && typeof values === 'object' ? values : {}
    for (const selected of selectedDefinitions(requestedScope, explicit, false)) {
      const definition = selected.definition
      const aliases = definition.aliases ?? definition.legacyIds
      const names = Array.isArray(aliases) ? aliases : typeof aliases === 'string' ? [aliases] : []
      const suppliedName = [definition.id, ...names].find(name => Object.hasOwn(entries, name))
      if (suppliedName == null || entries[suppliedName] === undefined) clearKnob(definition.id, selected.scope)
      else setKnob(definition.id, entries[suppliedName], selected.scope)
    }
  }
  function reset(requestedScope) {
    const explicit = arguments.length > 0
    for (const selected of selectedDefinitions(requestedScope, explicit, false)) clearKnob(selected.definition.id, selected.scope)
  }
  return Object.freeze({
    getKnob,
    setKnob,
    clearKnob,
    listKnobs: () => flattened.map(definition => ({ ...definition })),
    resolve,
    applyPreset,
    reset,
  })
}

let defaultKnobStore = createKnobStore()
export function initKnobs(definitions = []) { defaultKnobStore = createKnobStore(definitions) }
export function getKnob(...args) { return defaultKnobStore.getKnob(...args) }
export function setKnob(...args) { return defaultKnobStore.setKnob(...args) }
export function clearKnob(...args) { return defaultKnobStore.clearKnob(...args) }
export function listKnobs() { return defaultKnobStore.listKnobs() }
export function resolveKnob(id, options) {
  const selected = selectedOptionScope(options)
  return selected === undefined ? defaultKnobStore.resolve(id) : defaultKnobStore.resolve(id, selected)
}
export function applyKnobPreset(values, options = {}) {
  const selected = selectedOptionScope(options)
  return selected === undefined ? defaultKnobStore.applyPreset(values) : defaultKnobStore.applyPreset(values, selected)
}
export function resetKnobs(options = {}) {
  const selected = selectedOptionScope(options)
  return selected === undefined ? defaultKnobStore.reset() : defaultKnobStore.reset(selected)
}

export function setKnobValue(id, value, { route, scope, target, definition } = {}) {
  const selectedScope = selectedOptionScope({ route, scope })
  const resolved = target?.contentWindow ?? target ?? null
  if (!resolved) return selectedScope === undefined ? setKnob(id, value) : setKnob(id, value, selectedScope)
  if (!resolved.location) throw new TypeError('target must be a Window or iframe element')
  const key = buildKnobKey(id, { route: canonicalScopeForDefinition(definition, selectedScope) })
  const { path, params } = readTargetHash(resolved)
  params.set(key, serializeKnobValue(value, definition))
  writeTargetHash(resolved, path, params)
}

export function clearKnobValue(id, { route, scope, target, definition } = {}) {
  const selectedScope = selectedOptionScope({ route, scope })
  const resolved = target?.contentWindow ?? target ?? null
  if (!resolved) return selectedScope === undefined ? clearKnob(id) : clearKnob(id, selectedScope)
  if (!resolved.location) throw new TypeError('target must be a Window or iframe element')
  const { path, params } = readTargetHash(resolved)
  const canonicalScope = canonicalScopeForDefinition(definition, selectedScope)
  for (const key of knobKeysFor(id, definition, canonicalScope)) params.delete(key)
  writeTargetHash(resolved, path, params)
}
